import AppKit
import Carbon.HIToolbox

/// Writes history entries back to the pasteboard so other clipboard managers
/// can tell a paste-back from a new copy. nspasteboard.org asks a history app
/// putting earlier content back to name the original app as the source; the
/// write is also marked auto-generated ("the user had no intention to Copy
/// this content"), which managers that follow the convention skip, and with
/// Sukusho's own type so its monitor skips it.
nonisolated enum ClipboardWriter {
    static let autoGeneratedType = "org.nspasteboard.AutoGeneratedType"

    /// False when an image's file is gone or the pasteboard refused the write.
    @discardableResult
    static func write(_ entry: ClipboardEntry, richText: [String: Data], plain: Bool,
                      to pasteboard: NSPasteboard = .general, didWrite: ([NSPasteboardItem]) -> Void = { _ in }) -> Bool {
        guard let items = items(for: entry, richText: richText, plain: plain) else { return false }
        pasteboard.clearContents()
        guard pasteboard.writeObjects(items) else { return false }
        didWrite(items)
        return true
    }

    static func libraryItems(for entry: ClipboardEntry, richText: [String: Data], plain: Bool,
                             includeTIFF: Bool) async throws -> [NSPasteboardItem] {
        if entry.kind == .image {
            guard let url = entry.imageURL else {
                throw CocoaError(.fileNoSuchFile)
            }
            let item = try await ScreenshotClipboardImage.item(from: url, dataType: imageType(for: url),
                                                               includeTIFF: includeTIFF, snapshotName: entry.snapshotName(for: url))
            mark(item, source: entry.sourceBundleID)
            return [item]
        }
        guard let items = items(for: entry, richText: richText, plain: plain) else { throw CocoaError(.fileNoSuchFile) }
        return items
    }

    private static func items(for entry: ClipboardEntry, richText: [String: Data], plain: Bool) -> [NSPasteboardItem]? {
        var items: [NSPasteboardItem] = []
        switch entry.kind {
        case .text, .snippet:
            let item = NSPasteboardItem()
            item.setString(entry.text ?? "", forType: .string)
            if !plain { for (type, data) in richText { item.setData(data, forType: .init(type)) } }
            items = [item]
        case .files:
            let paths = (entry.text ?? "").split(separator: "\n").map(String.init)
            if plain {
                let item = NSPasteboardItem()
                item.setString(paths.joined(separator: "\n"), forType: .string)
                items = [item]
            } else {
                items = paths.map { path in
                    let item = NSPasteboardItem()
                    item.setString(URL(fileURLWithPath: path).absoluteString, forType: .fileURL)
                    item.setString((path as NSString).lastPathComponent, forType: .string)
                    return item
                }
            }
        case .image:
            guard let url = entry.imageURL,
                  let data = try? Data(contentsOf: url) else { return nil }
            let item = NSPasteboardItem()
            item.setData(data, forType: imageType(for: url))
            items = [item]
        }
        guard let first = items.first else { return nil }
        // A snippet was written here, so it has no other source.
        let source = entry.kind == .snippet ? Bundle.main.bundleIdentifier : entry.sourceBundleID
        mark(first, source: source)
        return items
    }

    private static func mark(_ item: NSPasteboardItem, source: String?) {
        item.setString(source ?? "", forType: .init(ClipboardCapturePolicy.sourceType))
        item.setData(Data(), forType: .init(autoGeneratedType))
        item.setData(Data(), forType: .init(ClipboardCapturePolicy.ownType))
    }

    private static func imageType(for url: URL) -> NSPasteboard.PasteboardType {
        switch url.pathExtension.lowercased() {
        case "jpg", "jpeg": .init("public.jpeg")
        case "heic": .init("public.heic")
        case "gif": .init("com.compuserve.gif")
        case "tif", "tiff": .tiff
        default: .png
        }
    }

    /// ⌘V into whatever is in front. Needs Accessibility (PostEvent).
    static func typeCommandV() {
        // shortcut: kVK_ANSI_V is V's key on ANSI layouts; a Dvorak user's ⌘V lives elsewhere. Map through the layout if that comes up.
        let source = CGEventSource(stateID: .combinedSessionState)
        for isDown in [true, false] {
            let event = CGEvent(keyboardEventSource: source, virtualKey: CGKeyCode(kVK_ANSI_V), keyDown: isDown)
            event?.flags = .maskCommand
            event?.post(tap: .cghidEventTap)
        }
    }
}
